// Shared navigation and metadata for the template-driven games.
for (const {kind,copy} of require('./games.cjs')) {
 for (const [lang,p] of Object.entries(module.exports)) {
  const l=copy[lang];
  if(l)Object.assign(p,{[kind]:l.route,[kind+'Title']:l.pageTitle,[kind+'Description']:l.pageDescription,[kind+'Heading']:l.title,[kind+'Label']:l.navLabel});
 }
}
// Topic browsing: the localized games index and one page per topic.
{
 const {section,index,topics}=require('./topics.cjs');
 for (const [lang,p] of Object.entries(module.exports)) {
  const i=index[lang];
  Object.assign(p,{topics:section[lang],topicsTitle:i.title,topicsDescription:i.description,topicsHeading:i.heading,topicsLabel:i.label});
  for(const t of topics){const c=t.copy[lang],kind='topic-'+t.id;Object.assign(p,{[kind]:section[lang]+c.slug+'/',[kind+'Title']:c.title,[kind+'Description']:c.description,[kind+'Heading']:c.heading,[kind+'Label']:c.name});}
 }
}
// Collections: one page per collection, beside the topic pages.
{
 const {section}=require('./topics.cjs'),{tags}=require('./tags.cjs');
 for (const [lang,p] of Object.entries(module.exports)) {
  for(const t of tags){const c=t.copy[lang],kind='tag-'+t.id;Object.assign(p,{[kind]:section[lang]+c.slug+'/',[kind+'Title']:c.title,[kind+'Description']:c.description,[kind+'Heading']:c.heading,[kind+'Label']:c.name});}
 }
}
